function solve(input) {
  const { tree } = input;
  if (!tree || tree.length === 0) return [];
  function invert(idx) {
    if (idx >= tree.length || tree[idx] === null) return null;
    const node = { val: tree[idx], left: invert(2 * idx + 1), right: invert(2 * idx + 2) };
    const tmp = node.left; node.left = node.right; node.right = tmp;
    return node;
  }
  const root = invert(0);
  const res = [];
  const q = [root];
  while (q.length > 0) {
    const curr = q.shift();
    if (curr) {
      res.push(curr.val);
      q.push(curr.left);
      q.push(curr.right);
    } else {
      res.push(null);
    }
  }
  while (res.length > 0 && res[res.length - 1] === null) res.pop();
  return res;
}
